\title{Paradoxes as Theorems: The Liar, Berry, and Russell Made Consistent}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\maketitle

\begin{abstract}
The Liar paradox (``this sentence is false''), Russell's paradox (the set of all sets that do not contain themselves), and Berry's paradox (the least integer not nameable in fewer than nineteen syllables) share a single logical skeleton: a sentence equivalent to its own negation. Classically this skeleton is toxic, because classical logic validates \emph{ex contradictione quodlibet} (explosion): a single contradiction proves everything. We show, with complete and explicit constructions, that all three paradoxes can be simultaneously realized as \emph{provable theorems} of a consistent (nontrivial, non-explosive) formal system, provided one abandons classical (Boolean) logic. The abandonment is not optional: we prove a sharp dichotomy. In any Boolean algebra a negation fixed point ($\comp{x}=x$) forces total collapse ($\bot=\top$), so no nontrivial Boolean-valued theory can host a self-negating sentence. On the positive side, Belnap's four-valued logic supplies a \emph{designated} negation fixed point, the glut value $\Bv$, and we construct an explicit six-sentence paraconsistent theory in which distinct Liar, Russell, and Berry sentences are all provable gluts while at least one sentence remains unprovable. We characterize gluts semantically, verify the De Morgan structure, and quantify paradoxicality via an inconsistency degree, which for our witness equals exactly three. Turning the paradoxes into consistent theorems is possible if and only if one leaves classical logic.
\end{abstract}

\section{Introduction}

\subsection{A shared skeleton}
Three famous antinomies look different but are structurally identical.
\begin{itemize}
\item \textbf{The Liar.} Let $L$ be ``$L$ is false.'' Then $L$ holds iff $\neg L$ holds.
\item \textbf{Russell.} Let $R=\{x: x\notin x\}$. Then $R\in R$ iff $R\notin R$.
\item \textbf{Berry.} Let $b$ be ``the least positive integer not nameable in fewer than nineteen syllables.'' The eighteen-syllable phrase names $b$, so $b$ is nameable in fewer than nineteen syllables iff it is not.
\end{itemize}
In each case a proposition $P$ is forced into the shape
\begin{equation}\label{eq:star}
P \iff \neg P. \tag{$\star$}
\end{equation}
The standard foundational response is prophylactic: forbid \eqref{eq:star} from being expressible (Tarski hierarchies, type theory, restricted comprehension).

\subsection{A different question}
We ask whether \eqref{eq:star} can be \emph{retained} as an honest theorem inside a system that is nevertheless \emph{consistent} in the sense of being \emph{nontrivial}: not every sentence is provable. The obstacle is not the contradiction but its classical amplification,
\[ \textbf{(EXP)}\qquad P,\ \neg P \vdash Q \quad\text{for every } Q, \]
\emph{explosion}. \textbf{Paraconsistent} logics are those in which (EXP) fails.

\subsection{Contributions}
\begin{enumerate}
\item \textbf{Boolean Collapse Theorem} (\S3): in any Boolean algebra, $\comp{x}=x\Rightarrow\bot=\top$.
\item \textbf{Belnap semantics} (\S4): four-valued negation, designation, meet/join; involutivity, De Morgan laws, and the Glut Characterization identifying $\Bv$ as the unique designated negation fixed point.
\item \textbf{Paraconsistent theory and six-sentence witness} (\S5): an explicit consistent theory in which three distinct paradox sentences are provable gluts while remaining nontrivial and non-explosive; a self-soundness schema; inconsistency degree three.
\item \textbf{The Dichotomy} (\S6): a consistent Liar exists in the four-valued world and cannot exist in any nontrivial Boolean world.
\end{enumerate}

\section{Preliminaries}
A \emph{truth-value algebra} is a set of values with a unary negation and (where needed) binary meet/join, plus a set of \emph{designated} values (``assertible / provable''). A sentence is a \emph{theorem} of a valued theory when its value is designated. A \emph{negation fixed point} is a value with $\neg x = x$ (Boolean: $\comp{x}=x$), the algebraic incarnation of \eqref{eq:star}. A valued theory is \emph{trivial} if every sentence is a theorem and \emph{consistent} (paraconsistently) if some sentence is not. It is \emph{explosive} if any glut forces every sentence to be designated.

\section{The classical obstruction}
Boolean algebras satisfy $x\wedge \comp{x}=\bot$ and $x\vee\comp{x}=\top$.

\begin{theorem}[Boolean Collapse]\label{thm:collapse}
Let $\alpha$ be a Boolean algebra and $x\in\alpha$ with $\comp{x}=x$. Then $\bot=\top$.
\end{theorem}
\begin{proof}
From the golden rules, $x\wedge\comp{x}=\bot$ and $x\vee\comp{x}=\top$. Substituting $\comp{x}=x$ gives $x\wedge x=\bot$ and $x\vee x=\top$; idempotence yields $x=\bot$ and $x=\top$, so $\bot=x=\top$.
\end{proof}

\begin{corollary}[No Classical Liar]\label{cor:noliar}
In any nontrivial Boolean algebra ($\bot\neq\top$) there is no $x$ with $\comp{x}=x$.
\end{corollary}
\begin{proof}
Contrapositive of Theorem~\ref{thm:collapse}.
\end{proof}

\begin{proposition}[Propositional Liar]
For every proposition $P$, not $(P\leftrightarrow\neg P)$.
\end{proposition}
\begin{proof}
Assume $P\leftrightarrow\neg P$. If $P$ then $\neg P$, contradiction; hence $\neg P$; then $P$, contradiction.
\end{proof}

\begin{proposition}[Classical Explosion]\label{prop:exp}
For all $P,Q$, if $P$ and $\neg P$ then $Q$.
\end{proposition}
\begin{proof}
From $P$ and $\neg P$ we obtain absurdity, whence any $Q$.
\end{proof}

\section{Belnap's four-valued logic}
The four values are $\Tv$ (true only), $\Fv$ (false only), $\Bv$ (both, a glut), $\Nv$ (neither, a gap). Negation is
\[ \neg\Tv=\Fv,\quad \neg\Fv=\Tv,\quad \neg\Bv=\Bv,\quad \neg\Nv=\Nv, \]
and the designated values are $\{\Tv,\Bv\}$; a sentence is provable iff its value is designated.

\begin{proposition}[Involutivity]
$\neg\neg v = v$ for every value $v$.
\end{proposition}
\begin{proof}
Check all four values.
\end{proof}

Order values by truth content $\Fv\le\Nv,\Bv\le\Tv$; conjunction $\wedge$ is meet, disjunction $\vee$ is join, with $\Bv\wedge\Nv=\Fv$ and $\Bv\vee\Nv=\Tv$.

\begin{theorem}[De Morgan laws]\label{thm:demorgan}
For all $a,b$: $\neg(a\wedge b)=\neg a\vee\neg b$ and $\neg(a\vee b)=\neg a\wedge\neg b$.
\end{theorem}
\begin{proof}
Exhaustive verification over the sixteen pairs; negation is an order-reversing involution.
\end{proof}

The four values thus form a De Morgan algebra. The Boolean golden rules fail: $\Bv\wedge\neg\Bv=\Bv\neq\Fv$, so non-contradiction fails.

\begin{theorem}[Glut Characterization]\label{thm:glut}
A value $v$ has both $v$ designated and $\neg v$ designated iff $v=\Bv$.
\end{theorem}
\begin{proof}
$\Bv$ satisfies both since $\neg\Bv=\Bv$ is designated. For $\Tv$, $\neg\Tv=\Fv$ is undesignated; $\Fv$ and $\Nv$ are themselves undesignated.
\end{proof}

\begin{corollary}[Designated negation fixed point]\label{cor:fixpoint}
There is a designated value $v$ with $\neg v=v$, namely $v=\Bv$.
\end{corollary}
Corollary~\ref{cor:fixpoint} supplies exactly the object Corollary~\ref{cor:noliar} forbids in the nontrivial Boolean world.

\section{A consistent paraconsistent theory}

\begin{definition}[Paraconsistent theory]
A \emph{paraconsistent theory} over a sentence set $S$ consists of a valuation $\mathrm{val}:S\to\{\Tv,\Fv,\Bv,\Nv\}$, a syntactic negation $\mathrm{sneg}:S\to S$, and the \emph{coherence} condition $\mathrm{val}(\mathrm{sneg}(s))=\neg\,\mathrm{val}(s)$ for all $s$. A sentence $s$ is \emph{provable} iff $\mathrm{val}(s)$ is designated, and a \emph{glut} iff both $s$ and $\mathrm{sneg}(s)$ are provable.
\end{definition}

\begin{theorem}[Self-soundness schema]\label{thm:self}
In any coherent theory, $s$ is a glut iff $\mathrm{val}(s)=\Bv$.
\end{theorem}
\begin{proof}
$s$ is a glut iff $\mathrm{val}(s)$ and $\mathrm{val}(\mathrm{sneg}(s))=\neg\,\mathrm{val}(s)$ are both designated; by Theorem~\ref{thm:glut} this holds iff $\mathrm{val}(s)=\Bv$.
\end{proof}

\subsection{The six-sentence witness}
Take $S=\{s_0,\dots,s_5\}$ with
\[ \mathrm{val}=(\Bv,\Bv,\Bv,\Tv,\Fv,\Nv), \]
\[ \mathrm{sneg}: s_0\mapsto s_0,\ s_1\mapsto s_1,\ s_2\mapsto s_2,\ s_3\mapsto s_4,\ s_4\mapsto s_3,\ s_5\mapsto s_5. \]
Here $s_0,s_1,s_2$ are the Liar, Russell, and Berry witnesses; $s_3$ a plain truth, $s_4$ a plain falsehood, $s_5$ a gap.

\begin{lemma}[Coherence]
The data forms a paraconsistent theory.
\end{lemma}
\begin{proof}
For $s_0,s_1,s_2$: fixed by $\mathrm{sneg}$ and $\neg\Bv=\Bv$. For $s_3$: $\mathrm{val}(s_4)=\Fv=\neg\Tv$. For $s_4$: $\mathrm{val}(s_3)=\Tv=\neg\Fv$. For $s_5$: $\Nv=\neg\Nv$.
\end{proof}

\begin{theorem}[Three paradoxes are theorems]
$s_0,s_1,s_2$ are pairwise distinct and each is a provable glut.
\end{theorem}
\begin{proof}
Distinctness by inspection; each has value $\Bv$ (designated) and equals its own negation, so by Theorem~\ref{thm:self} each is a glut.
\end{proof}

\begin{theorem}[Consistency / nontriviality]\label{thm:nontrivial}
$s_4$ is not a theorem.
\end{theorem}
\begin{proof}
$\mathrm{val}(s_4)=\Fv$ is not designated.
\end{proof}

\begin{theorem}[Non-explosion]
The theory contains a glut ($s_0$) yet has an unprovable sentence ($s_4$); explosion fails.
\end{theorem}
\begin{proof}
Combine the previous two theorems.
\end{proof}

\begin{definition}[Inconsistency degree]
The \emph{inconsistency degree} of a paraconsistent theory over a finite $S$ is the number of $\Bv$-valued sentences.
\end{definition}

\begin{theorem}[Degree of the witness]
The six-sentence witness has inconsistency degree exactly three.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:self} the gluts are the $\Bv$-valued sentences, namely $s_0,s_1,s_2$.
\end{proof}

\section{The dichotomy}
\begin{theorem}[Consistent Liar requires non-classical logic]\label{thm:dichotomy}
The property ``there exists a designated truth value equal to its own negation'' holds in Belnap's four-valued logic and fails in every nontrivial Boolean algebra:
\begin{enumerate}
\item there is a Belnap value $v$ with $\neg v=v$ and $v$ designated ($v=\Bv$); and
\item for every nontrivial Boolean algebra $\alpha$ and every $x\in\alpha$, $\comp{x}\neq x$.
\end{enumerate}
\end{theorem}
\begin{proof}
Part (1) is Corollary~\ref{cor:fixpoint}; part (2) is Corollary~\ref{cor:noliar}.
\end{proof}

\begin{corollary}
Making the Liar, Russell, and Berry paradoxes into provable theorems of a consistent formal system is possible if and only if classical (Boolean) logic is rejected---equivalently, if and only if one admits a designated negation fixed point, forcing the failure of non-contradiction.
\end{corollary}

\section{Applications and discussion}
Belnap's values were designed for inconsistency-tolerant databases and knowledge bases: mark a fact $\Bv$ when told both true and false and keep reasoning, the non-explosion guarantee being the formal license. The self-soundness schema separates overdetermined ($\Bv$) from underdetermined ($\Nv$) pathologies of self-reference, and the dichotomy turns the paradoxes into a measurement of a logical assumption rather than a defect to exile. A limitation of the witness is that the paradoxes are posited rather than derived by diagonalization; bridging to a G\"odel-style fixed point is the natural next step.

\section{Future directions}
\begin{enumerate}
\item A full propositional paraconsistent calculus with connectives interpreted through the four-valued operations and a soundness/completeness theorem for the designated-value consequence relation.
\item Algebraic generality: characterize which finite De Morgan bilattices admit a designated negation fixed point.
\item Encoding genuine self-reference via a paraconsistent fixed-point lemma so that Liar/Russell/Berry are derived rather than posited.
\item A Berry-specific refinement from an explicit least-undefinable-number construction.
\item Study of the inconsistency degree as an invariant under theory extensions and morphisms.
\end{enumerate}

\section{Conclusion}
In any nontrivial Boolean algebra a value equal to its own negation forces collapse, so classical logic cannot host a consistent self-negating sentence. Belnap's four-valued logic supplies the missing designated fixed point $\Bv$, and an explicit six-sentence theory makes the Liar, Russell, and Berry simultaneous provable theorems while remaining nontrivial and non-explosive, with inconsistency degree exactly three. Consistent paradox-theorems exist exactly in the non-classical world.

\end{document}

