"""Demo: gluts are exactly the value B, and the six-sentence witness."""
from __future__ import annotations
from typing import Dict, List, Tuple

VALUES: Tuple[str, ...] = ("T", "F", "B", "N")
NEG: Dict[str, str] = {"T": "F", "F": "T", "B": "B", "N": "N"}
DES: Dict[str, bool] = {"T": True, "F": False, "B": True, "N": False}


def glut_values() -> List[str]:
    """Values v with both v and neg(v) designated (the paradox signature)."""
    return [v for v in VALUES if DES[v] and DES[NEG[v]]]


def main() -> None:
    print("Values that are gluts:", glut_values())      # ['B']
    assert glut_values() == ["B"]
    print("The unique paradox value is B (both true and false).")


if __name__ == "__main__":
    main()

"""Demo: inconsistency degree of a paraconsistent theory."""
from __future__ import annotations
from typing import List

NEG = {"T": "F", "F": "T", "B": "B", "N": "N"}
DES = {"T": True, "F": False, "B": True, "N": False}


def inconsistency_degree(val: List[str]) -> int:
    """Number of glut-valued (B) sentences."""
    return sum(1 for v in val if v == "B")


def report(val: List[str], sneg: List[int]) -> None:
    coherent = all(val[sneg[s]] == NEG[val[s]] for s in range(len(val)))
    provable = [DES[v] for v in val]
    print(f"  values           = {val}")
    print(f"  coherent         = {coherent}")
    print(f"  provable         = {provable}")
    print(f"  inconsistency    = {inconsistency_degree(val)}")


def main() -> None:
    print("Witness (Liar/Russell/Berry gluts):")
    report(["B", "B", "B", "T", "F", "N"], [0, 1, 2, 4, 3, 5])
    print("Classical fragment (no gluts):")
    report(["T", "F"], [1, 0])
    assert inconsistency_degree(["B", "B", "B", "T", "F", "N"]) == 3


if __name__ == "__main__":
    main()

