from typing import Dict, List

NEG: Dict[str, str] = {"T": "F", "F": "T", "B": "B", "N": "N"}
DES: Dict[str, bool] = {"T": True, "F": False, "B": True, "N": False}


def is_glut(value: str) -> bool:
    """A value is a glut iff it and its negation are both designated."""
    return DES[value] and DES[NEG[value]]


def theory_gluts(val: List[str], sneg: List[int]) -> List[int]:
    """Return the indices of glut (paradox) sentences of a coherent theory.

    Coherence (val[sneg[s]] == NEG[val[s]]) makes 'sentence s is a glut'
    equivalent to 'val[s] == B', so a single value lookup suffices per sentence.
    """
    assert all(val[sneg[s]] == NEG[val[s]] for s in range(len(val)))
    return [s for s in range(len(val)) if is_glut(val[s])]

