from typing import Dict, List

NEG: Dict[str, str] = {"T": "F", "F": "T", "B": "B", "N": "N"}
DES: Dict[str, bool] = {"T": True, "F": False, "B": True, "N": False}


def is_coherent(val: List[str], sneg: List[int]) -> bool:
    """Check val(sneg(s)) == neg(val(s)) for every sentence s."""
    return all(val[sneg[s]] == NEG[val[s]] for s in range(len(val)))


def is_consistent(val: List[str]) -> bool:
    """Nontrivial: some sentence is not designated (not provable)."""
    return any(not DES[v] for v in val)


def is_non_explosive(val: List[str]) -> bool:
    """A glut is present yet some sentence is unprovable."""
    has_glut = any(v == "B" for v in val)
    has_unprovable = any(not DES[v] for v in val)
    return has_glut and has_unprovable


def certify(val: List[str], sneg: List[int]) -> Dict[str, bool]:
    """Full certificate for a candidate paraconsistent theory."""
    return {
        "coherent": is_coherent(val, sneg),
        "consistent": is_consistent(val),
        "non_explosive": is_non_explosive(val),
    }

